/* @component: input-check */
(function () {
  function initCheckboxes() {
    document.querySelectorAll('.input-check').forEach(function (container) {
      if (container.dataset.initialized === 'true') return;
      container.dataset.initialized = 'true';
      const input = container.querySelector('input[type="checkbox"]');
      const label = container.querySelector('label');
      if (input && label) {
        const uniqueId = 'check-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6);
        input.id = uniqueId;
        label.htmlFor = uniqueId;
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initCheckboxes);
  } else {
    initCheckboxes();
  }
  setTimeout(initCheckboxes, 100);
})();
/* @end: input-check */
